item.command:
/bin/bash -lc "cat > package.json <<'EOF'
{
  \"name\": \"store\",
  \"private\": true,
  \"scripts\": {
    \"dev\": \"next dev\",
    \"build\": \"next build\",
    \"start\": \"next start\",
    \"lint\": \"next lint\"
  },
  \"dependencies\": {
    \"next\": \"14.2.0\",
    \"react\": \"18.2.0\",
    \"react-dom\": \"18.2.0\"
  },
  \"devDependencies\": {
    \"typescript\": \""'^5.4.5",
    "@types/node": "''^20.12.7",
    "@types/react": "''^18.2.79"
  }
}
EOF
mkdir -p src/app
cat > src/app/layout.tsx <<'"'EOF'
import type { Metadata } from 'next';
import type { ReactNode } from 'react';

export const metadata: Metadata = {
  title: 'Store',
  description: 'Online store',
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang=\"en\">
      <body>{children}</body>
    </html>
  );
}
EOF
cat > src/app/page.tsx <<'EOF'
export default function HomePage() {
  return <main><h1>Store</h1></main>;
}
EOF
cat > src/pay.ts <<'EOF'
/** Read the Stripe secret only in server-side code. Never prefix secret keys with NEXT_PUBLIC_. */
export function getStripeSecretKey(): string {
  const key = process.env.STRIPE_SECRET_KEY;
  if ("'!key) {
    throw new Error('"'STRIPE_SECRET_KEY is not configured');
  }
  return key;
}
EOF
cat > .env.example <<'EOF'
# Configure these in Vercel Project Settings → Environment Variables.
STRIPE_SECRET_KEY=
DATABASE_URL=
EOF
cat > .gitignore <<'EOF'
node_modules
.next
out
.env
.env.*
"'!.env.example
.vercel
EOF
cat > next.config.js <<'"'EOF'
/** @type {import('next').NextConfig} */
const nextConfig = {
  poweredByHeader: false,
};

module.exports = nextConfig;
EOF
cat > tsconfig.json <<'EOF'
{
  \"compilerOptions\": {
    \"target\": \"es5\",
    \"lib\": [\"dom\", \"dom.iterable\", \"esnext\"],
    \"allowJs\": true,
    \"skipLibCheck\": true,
    \"strict\": true,
    \"noEmit\": true,
    \"esModuleInterop\": true,
    \"module\": \"esnext\",
    \"moduleResolution\": \"bundler\",
    \"resolveJsonModule\": true,
    \"isolatedModules\": true,
    \"jsx\": \"preserve\",
    \"incremental\": true,
    \"plugins\": [{ \"name\": \"next\" }],
    \"paths\": { \"@/*\": [\"./src/*\"] }
  },
  \"include\": [\"next-env.d.ts\", \".next/types/**/*.ts\", \"**/*.ts\", \"**/*.tsx\"],
  \"exclude\": [\"node_modules\"]
}
EOF
cat > README.md <<'EOF'
# Store

## Deploy on Vercel

Import this repository into Vercel and deploy with the Next.js framework preset. Vercel detects the framework and uses "'`npm run build` automatically.

Set these variables in **Project Settings → Environment Variables** for the Production environment (and Preview/Development if those deployments need them):

- `STRIPE_SECRET_KEY` — server-only Stripe secret key. Never expose it with a `NEXT_PUBLIC_` prefix.
- `DATABASE_URL` — database connection string.

Redeploy after changing environment variables. `.env.local` is for local development only and is excluded from Git; `.env.example` documents the required names without credentials.

## Local development

Install dependencies with `npm install`, copy `.env.example` to `.env.local`, fill in local values, then run `npm run dev`.
EOF'

